CREATE DEFINER=`root`@`localhost` PROCEDURE `ActualizarDatosPersonales` (IN `p_dni` VARCHAR(20), IN `p_apellido_paterno` VARCHAR(50), IN `p_apellido_materno` VARCHAR(50), IN `p_nombres` VARCHAR(100), IN `p_fecha_nacimiento` DATE, IN `p_distrito_nacimiento` VARCHAR(50), IN `p_provincia_nacimiento` VARCHAR(50), IN `p_departamento_nacimiento` VARCHAR(50), IN `p_sexo` VARCHAR(10), IN `p_nacionalidad` VARCHAR(50), IN `p_idioma` VARCHAR(50))   BEGIN
