CREATE DEFINER=`root`@`localhost` PROCEDURE `EditarEmergencia` (IN `p_id_emergencia` INT, IN `p_numero_contacto` VARCHAR(15), IN `p_nombre_contacto` VARCHAR(255), IN `p_parentesco_contacto` VARCHAR(50))   BEGIN
