CREATE DEFINER=`root`@`localhost` PROCEDURE `insertar_o_actualizar_residencia` (IN `p_dni` VARCHAR(15), IN `p_id_año_escolar` INT, IN `p_distrito_domicilio` VARCHAR(255), IN `p_urb_domicilio` VARCHAR(255), IN `p_calle_domicilio` VARCHAR(255), IN `p_num_domicilio` VARCHAR(10), IN `p_telefono_padre` VARCHAR(15), IN `p_telefono_madre` VARCHAR(15), IN `p_alergias` TEXT, IN `p_enfermedades_cronicas` TEXT, IN `p_imagen_estudiante` MEDIUMBLOB, IN `p_id_grado_estudiante` INT)   BEGIN
    -- Verificar si ya existe el registro
    IF EXISTS (
        SELECT 1
        FROM residencia
        WHERE dni = p_dni AND id_año_escolar = p_id_año_escolar
    ) THEN
        -- Si existe, actualizar el registro
        UPDATE residencia
        SET
            distrito_domicilio = p_distrito_domicilio,
            urb_domicilio = p_urb_domicilio,
            calle_domicilio = p_calle_domicilio,
            num_domicilio = p_num_domicilio,
            telefono_padre = p_telefono_padre,
            telefono_madre = p_telefono_madre,
            alergias = p_alergias,
            enfermedades_cronicas = p_enfermedades_cronicas,
            imagen_estudiante = p_imagen_estudiante,
            id_grado_estudiante = p_id_grado_estudiante
        WHERE dni = p_dni AND id_año_escolar = p_id_año_escolar;
    ELSE
        -- Si no existe, insertar un nuevo registro
            dni, id_año_escolar, distrito_domicilio, urb_domicilio,
            calle_domicilio, num_domicilio, telefono_padre, telefono_madre,
            alergias, enfermedades_cronicas, imagen_estudiante
        )
        VALUES (
            p_dni, p_id_año_escolar, p_distrito_domicilio, p_urb_domicilio,
            p_calle_domicilio, p_num_domicilio, p_telefono_padre, p_telefono_madre,
            p_alergias, p_enfermedades_cronicas, p_imagen_estudiante,p_id_grado_estudiante
        );
    END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `insertar_o_actualizar_sacramento` (IN `p_dni` VARCHAR(15), IN `p_id_año_escolar` INT, IN `p_bautizado` VARCHAR(3), IN `p_parroquia_bautizo` VARCHAR(255), IN `p_primera_comunion` VARCHAR(3), IN `p_confirmacion` VARCHAR(3), IN `p_asistencia_misa` VARCHAR(3), IN `p_parroquia_misa` VARCHAR(255))   BEGIN
