CREATE DEFINER=`root`@`localhost` PROCEDURE `registrar_padre2` (IN `p_dni` VARCHAR(15), IN `p_id_año_escolar` INT, IN `p_documento` VARCHAR(50), IN `p_nombre_completo` VARCHAR(255), IN `p_tipo_parentesco` VARCHAR(50), IN `p_fecha_nacimiento_padre` DATE, IN `p_distrito_nacimiento` VARCHAR(255), IN `p_correo` VARCHAR(100), IN `p_telefono` VARCHAR(20), IN `p_direccion` VARCHAR(255), IN `p_vive_con_hijo` VARCHAR(3), IN `p_nacionalidad` VARCHAR(50), IN `p_religion` VARCHAR(100), IN `p_grado_instruccion` VARCHAR(100), IN `p_profesion` VARCHAR(100), IN `p_centro_trabajo` VARCHAR(255), IN `p_trabajador_ipnm` VARCHAR(3), IN `p_ex_alumno` VARCHAR(3), IN `p_año_egreso` VARCHAR(10), IN `p_nombre_ie` VARCHAR(255), IN `p_condicion_padres` VARCHAR(255), IN `p_foto_padre` BLOB)   BEGIN
    DECLARE v_error_message VARCHAR(255);
    DECLARE v_count INT;

    -- Manejo de excepciones
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 v_error_message = MESSAGE_TEXT;
        ROLLBACK;  -- Revertir los cambios si hay un error
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_error_message;  -- Enviar el mensaje de error
    END;

    -- Inicia una transacción
    START TRANSACTION;

    -- Verificar si ya existen 2 registros para ese DNI y Año Escolar
    SELECT COUNT(*) INTO v_count 
    FROM padres 
    WHERE dni = p_dni AND id_año_escolar = p_id_año_escolar;

    -- Si ya existen 2 registros, no permitir la inserción
    IF v_count >= 2 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ya existen 2 registros para este DNI y Año Escolar.';
    ELSE
        -- Si hay menos de 2 registros, insertamos o actualizamos
        -- Intentar insertar los datos
            dni, 
            id_año_escolar, 
            documento, 
            nombre_completo, 
            tipo_parentesco, 
            fecha_nacimiento_padre, 
            distrito_nacimiento, 
            correo, 
            telefono, 
            direccion, 
            vive_con_hijo, 
            nacionalidad, 
            religion, 
            grado_instruccion, 
            profesion, 
            centro_trabajo, 
            trajabador_ipnm, 
            ex_alumno, 
            año_egreso, 
            nombre_ie, 
            condicion_padres, 
            foto_padre
        ) 
        VALUES (
            p_dni, 
            p_id_año_escolar, 
            p_documento, 
            p_nombre_completo, 
            p_tipo_parentesco, 
            p_fecha_nacimiento_padre, 
            p_distrito_nacimiento, 
            p_correo, 
            p_telefono, 
            p_direccion, 
            p_vive_con_hijo, 
            p_nacionalidad, 
            p_religion, 
            p_grado_instruccion, 
            p_profesion, 
            p_centro_trabajo, 
            p_trabajador_ipnm, 
            p_ex_alumno, 
            p_año_egreso, 
            p_nombre_ie, 
            p_condicion_padres, 
            p_foto_padre
        );
    END IF;

    -- Commit si todo salió bien
    COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `registrar_usuario` (IN `p_dni` VARCHAR(20), IN `p_password` VARCHAR(255))   BEGIN
    -- Verificar si ya existe un usuario con el mismo DNI
    IF (SELECT COUNT(*) FROM usuario WHERE dni = p_dni) > 0 THEN
        SIGNAL SQLSTATE '45000' 
        SET MESSAGE_TEXT = 'El DNI ya está registrado.';
    ELSE
        -- Insertar el nuevo usuario con la contraseña encriptada
            dni,
            contra
        )
        VALUES (
            p_dni,
            p_password 
        );
    END IF;
END$$

